func TestTabCyclesArgsCompletions(t *testing.T) {
	t.Parallel()

	m := newModel(context.Background(), nil)
	m.focus = focusDetailArgs
	m.editor = newBookmarkEditor(config.Bookmark{ArgsText: "--ctx"}, false, tuiweave.Dark())
	m.editor.args.Focus()
