	// Tab to populate autocomplete
	m.handleArgCompletionTab(argCompletionForward)
	if !m.ac.Focused() || m.ac.FilteredLen() == 0 {
		t.Fatalf("expected autocomplete to be populated after tab")
	}
	first := m.ac.SelectedItem().Value
	if first == "" {
		t.Fatalf("expected a selected item in autocomplete")
	}

	// Navigate down in autocomplete
	m.ac, _ = m.ac.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyDown}))
	second := m.ac.SelectedItem().Value
	if first == second {
		t.Fatalf("down arrow should cycle to a different completion, still got %q", second)
