	if !strings.HasPrefix(second, "--ctx") {
		t.Fatalf("cycled completion should keep the original prefix, got %q", second)
	}

	// Navigate up in autocomplete
	m.ac, _ = m.ac.Update(tea.KeyPressMsg(tea.Key{Code: tea.KeyUp}))
	if m.ac.SelectedItem().Value != first {
		t.Fatalf("up arrow should cycle back to the previous completion, got %q want %q", m.ac.SelectedItem().Value, first)
	}
}

